def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_prev_bids = []
    weak_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) <= DAILY_SALARY * 0.6 or opp.get('hp', 0) <= 2:
                weak_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev['bid']
                prev_bids.append(bid)
                if opp.get('budget', 0) > DAILY_SALARY and opp.get('hp', 0) >= 4:
                    strong_prev_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    slots = supply / WATER_REQ
    if slots >= 3:
        supply_pressure = 0
    elif slots >= 2:
        supply_pressure = 1
    else:
        supply_pressure = 2

    highest_prev = max(prev_bids) if prev_bids else 0.0
    strong_high = max(strong_prev_bids) if strong_prev_bids else highest_prev

    if hp <= 2 or no_water_days >= 2:
        emergency = True
    else:
        emergency = False

    if emergency:
        bid = max(DAILY_SALARY * 0.95, strong_high + 2.5)
    elif supply_pressure == 2:
        bid = max(DAILY_SALARY * 0.82, strong_high + 1.2)
    elif supply_pressure == 1:
        bid = max(DAILY_SALARY * 0.58, strong_high * 0.72)
    else:
        bid = DAILY_SALARY * 0.34

    if weak_count >= 2 and not emergency:
        bid *= 0.88

    if hp >= 8 and no_water_days == 0 and supply_pressure == 0:
        bid = min(bid, DAILY_SALARY * 0.3)

    if day >= 8 and hp <= 4:
        bid = max(bid, DAILY_SALARY * 0.9)

    if budget < DAILY_SALARY * 1.2 and not emergency:
        bid = min(bid, budget * 0.55)

    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    budget = my_status['budget']
    hp = my_status['hp']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return float(min(budget, 10))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_prev = max(yesterday_bids) if yesterday_bids else 50

    if hp <= 3:
        return float(min(budget, max_prev * 1.2))

    if supply < 18:
        return float(min(budget, max_prev * 1.05))
    elif supply > 22:
        return float(min(budget, max(30, max_prev * 0.7)))
    else:
        return float(min(budget, max_prev * 0.9))
